vulnerable_code:
app.post('/api/profile/create', async (req, res) => {
  const item = await Profile.create(req.body);
  res.json(item);
});

corrected_code:
app.post('/api/profile/create', async (req, res) => {
  const data = { ...req.body, userId: req.user.id };
  const item = await Profile.create(data);
  res.json(item);
});
